export interface Material {
  id: string;
  name: string;
  materialType: string;
  category: string;
  specifications: string;
  supplier: string;
  barcode: string;
  unit: string;
  minStock: number;
  currentStock: number;
  isNew: boolean;
}

export interface Transaction {
  id: string;
  type: 'in' | 'out'; // Added to distinguish movement
  materialId: string;
  materialName: string;
  materialType: string;
  supplier: string;
  category: string;
  barcode: string;
  quantity: number;
  unit: string;
  recipient: string; // For 'in', this can be the 'source' or 'returned by'
  notes?: string;
  date: string;
}

export interface User {
  id:string;
  username: string;
  password?: string;
  role: 'admin' | 'visitor';
}

export type Page = 'dashboard' | 'materials' | 'transactions' | 'reports' | 'settings' | 'new-entries' | 'users';

export interface SettingsData {
  companyName: string;
  companyAddress: string;
  companyLogo: string; // Base64 encoded image
  signatureNames: {
    keeper: string;
    accountant: string;
    manager: string;
  };
  gistUrl?: string;
  githubToken?: string;
}

export interface AllData {
  settings: SettingsData;
  materials: Material[];
  transactions: Transaction[];
  users: Omit<User, 'password'>[];
}

import { User, Material, Transaction, SettingsData, AllData } from '@/types';

// --- INITIAL DATA & HELPERS ---

const USERS_KEY = 'warehouse_users';
const MATERIALS_KEY = 'warehouse_materials';
const TRANSACTIONS_KEY = 'warehouse_transactions';
const SETTINGS_KEY = 'warehouse_settings';
const CURRENT_USER_KEY = 'currentUser';

const defaultLogoSvg = 'data:image/svg+xml;base64,';

const getFromStorage = <T>(key: string, defaultValue: T): T => {
  try {
    const item = localStorage.getItem(key);
    return item ? JSON.parse(item) : defaultValue;
  } catch (error) {
    console.error(`Error reading from localStorage key “${key}”:`, error);
    return defaultValue;
  }
};

const saveToStorage = <T>(key: string, value: T) => {
  try {
    const item = JSON.stringify(value);
    localStorage.setItem(key, item);
  } catch (error) {
    console.error(`Error writing to localStorage key “${key}”:`, error);
  }
};

const initializeData = () => {
    if (!localStorage.getItem(USERS_KEY)) {
        const initialUsers: User[] = [
            { id: '1', username: 'admin', password: 'admin123', role: 'admin' },
            { id: '2', username: 'user', password: 'user123', role: 'visitor' },
        ];
        saveToStorage(USERS_KEY, initialUsers);
    }

    if (!localStorage.getItem(MATERIALS_KEY)) {
        const initialMaterials: Material[] = [
            { id: 'm1', name: 'لابتوب ديل', materialType: 'DELL-LT-001', unit: 'حبة', category: 'أجهزة إلكترونية', specifications: 'Core i7, 16GB RAM, 512GB SSD', supplier: 'شركة التكنولوجيا الحديثة', barcode: '1234567890123', minStock: 5, currentStock: 15, isNew: false },
            { id: 'm2', name: 'شاشة سامسونج 24 بوصة', materialType: 'SAM-SC-024', unit: 'حبة', category: 'أجهزة إلكترونية', specifications: '24" Full HD, 75Hz', supplier: 'سامسونج العالمية', barcode: '1234567890124', minStock: 10, currentStock: 8, isNew: false },
        ];
        saveToStorage(MATERIALS_KEY, initialMaterials);
    }

    if (!localStorage.getItem(TRANSACTIONS_KEY)) {
        saveToStorage(TRANSACTIONS_KEY, []);
    }

    if (!localStorage.getItem(SETTINGS_KEY)) {
        const initialSettings: SettingsData = {
            companyName: 'اسم الشركة',
            companyAddress: 'العنوان هنا',
            companyLogo: defaultLogoSvg,
            signatureNames: { keeper: 'أمين المستودع', accountant: 'المحاسب', manager: 'المدير العام' },
            gistUrl: '',
            githubToken: '',
        };
        saveToStorage(SETTINGS_KEY, initialSettings);
    }
};

initializeData();

const syncDataToGist = async () => {
    const settings = getSettings();
    if (!settings.gistUrl || !settings.githubToken) return;
    const match = settings.gistUrl.match(/gist\.github(?:usercontent)?\.com\/[^\/]+\/([a-f0-9]+)/);
    if (!match) return;
    const gistId = match[1];
    const allData = exportAllData();
    const filename = settings.gistUrl.split('/').pop() || 'warehouse-data.json';
    try {
        await fetch(`https://api.github.com/gists/${gistId}`, {
            method: 'PATCH',
            headers: { 'Authorization': `token ${settings.githubToken}`, 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json' },
            body: JSON.stringify({ files: { [filename]: { content: JSON.stringify(allData, null, 2) } } }),
        });
    } catch (error) { console.error("Gist sync error:", error); }
};

export const initializeDataSource = async (): Promise<{ success: boolean; message?: string }> => {
    const settings = getSettings();
    if (!settings.gistUrl) return { success: true, message: 'Using local data.' };
    try {
        const response = await fetch(settings.gistUrl, { cache: 'no-store' });
        if (!response.ok) throw new Error(`Failed to fetch data from Gist.`);
        const data = await response.json();
        importAllData(data);
        return { success: true, message: 'Data loaded from Gist.' };
    } catch (error) { return { success: false, message: (error as Error).message }; }
};

export const authenticateUser = (username: string, password: string): User | null => {
    const users = getFromStorage<User[]>(USERS_KEY, []);
    const user = users.find(u => u.username === username && u.password === password);
    if (user) { sessionStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user)); return user; }
    return null;
};

export const getCurrentUser = (): User | null => {
  try {
    const userJson = sessionStorage.getItem(CURRENT_USER_KEY);
    return userJson ? JSON.parse(userJson) : null;
  } catch { return null; }
};

export const getUsers = (): User[] => getFromStorage<User[]>(USERS_KEY, []);
export const addUser = (userData: Omit<User, 'id'>): User => {
    const users = getUsers();
    if (users.some(u => u.username === userData.username)) throw new Error('Username already exists');
    const newUser: User = { ...userData, id: `u${Date.now()}` };
    saveToStorage(USERS_KEY, [...users, newUser]);
    syncDataToGist();
    return newUser;
};

export const updateUser = (updatedUser: User): User => {
    let users = getUsers();
    const currentUser = getCurrentUser();
    if (users.some(u => u.username === updatedUser.username && u.id !== updatedUser.id)) throw new Error('Username already exists');
    users = users.map(u => (u.id === updatedUser.id ? updatedUser : u));
    saveToStorage(USERS_KEY, users);
    syncDataToGist();
    if (currentUser && currentUser.id === updatedUser.id) sessionStorage.setItem(CURRENT_USER_KEY, JSON.stringify(updatedUser));
    return updatedUser;
};

export const deleteUser = (userId: string): void => {
    saveToStorage(USERS_KEY, getUsers().filter(u => u.id !== userId));
    syncDataToGist();
};

export const getMaterials = (): Material[] => getFromStorage<Material[]>(MATERIALS_KEY, []);
export const addMaterial = (materialData: Omit<Material, 'id' | 'isNew'>): Material => {
    const materials = getMaterials();
    const newMaterial: Material = { ...materialData, id: `m${Date.now()}`, isNew: true };
    saveToStorage(MATERIALS_KEY, [...materials, newMaterial]);
    syncDataToGist();
    return newMaterial;
};

export const updateMaterial = (updatedMaterial: Material): Material => {
    const materials = getMaterials().map(m => m.id === updatedMaterial.id ? updatedMaterial : m);
    saveToStorage(MATERIALS_KEY, materials);
    syncDataToGist();
    return updatedMaterial;
};

export const acknowledgeNewMaterial = (materialId: string): void => {
    const material = getMaterials().find(m => m.id === materialId);
    if(material) updateMaterial({ ...material, isNew: false });
};

export const deleteMaterial = (materialId: string): void => {
    saveToStorage(MATERIALS_KEY, getMaterials().filter(m => m.id !== materialId));
    syncDataToGist();
};

export const getTransactions = (): Transaction[] => getFromStorage<Transaction[]>(TRANSACTIONS_KEY, []);

export const addTransaction = (transactionData: Omit<Transaction, 'id' | 'date' | 'materialName' | 'supplier' | 'category' | 'barcode' | 'unit' | 'materialType'>): Transaction => {
    const transactions = getTransactions();
    let materials = getMaterials();
    const material = materials.find(m => m.id === transactionData.materialId);

    if (!material) throw new Error('Material not found');

    if (transactionData.type === 'out' && material.currentStock < transactionData.quantity) {
        throw new Error('Not enough stock available');
    }

    const newTransaction: Transaction = {
        ...transactionData,
        id: `t${Date.now()}`,
        date: new Date().toISOString(),
        materialName: material.name,
        materialType: material.materialType,
        supplier: material.supplier,
        category: material.category,
        barcode: material.barcode,
        unit: material.unit,
    };

    // Calculate new stock based on type
    const stockChange = transactionData.type === 'in' ? transactionData.quantity : -transactionData.quantity;
    const updatedMaterial = { ...material, currentStock: material.currentStock + stockChange };
    materials = materials.map(m => m.id === updatedMaterial.id ? updatedMaterial : m);

    saveToStorage(MATERIALS_KEY, materials);
    saveToStorage(TRANSACTIONS_KEY, [...transactions, newTransaction]);
    syncDataToGist();

    return newTransaction;
};

export const getSettings = (): SettingsData => getFromStorage<SettingsData>(SETTINGS_KEY, { companyName: '', companyAddress: '', companyLogo: '', signatureNames: { keeper: '', accountant: '', manager: '' }, gistUrl: '', githubToken: '' });
export const saveSettings = (settings: SettingsData): void => { saveToStorage(SETTINGS_KEY, settings); };

export const exportAllData = (): AllData => {
    return { settings: getSettings(), materials: getMaterials(), transactions: getTransactions(), users: getUsers().map(({ password, ...user }) => user) };
};

export const importAllData = (data: AllData): void => {
    if (!data || !data.settings) throw new Error('Invalid data format');
    saveToStorage(SETTINGS_KEY, data.settings);
    saveToStorage(MATERIALS_KEY, data.materials);
    saveToStorage(TRANSACTIONS_KEY, data.transactions);
};

import React, { useState } from 'react';
import { Material, SettingsData, Transaction } from '@/types';
import { addMaterial, updateMaterial, deleteMaterial, acknowledgeNewMaterial, addTransaction } from '@/services/mockApi';
import { Plus, Edit, Trash2, AlertTriangle, Printer, Download, CheckCircle, PlusCircle } from 'lucide-react';
import * as XLSX from 'xlsx';

interface MaterialsProps {
  materials: Material[];
  onDataChange: () => void;
  userRole: 'admin' | 'visitor';
  settings: SettingsData | null;
}

// Modal for Adding/Returning Stock (Incremental)
const StockInModal: React.FC<{ material: Material; onClose: () => void; onSave: (amount: number, reason: string, note: string) => void; }> = ({ material, onClose, onSave }) => {
    const [amount, setAmount] = useState(1);
    const [reason, setReason] = useState('توريد جديد');
    const [note, setNote] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(amount, reason, note);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md">
                <h2 className="text-xl font-bold mb-2">إضافة كمية / مرتجع</h2>
                <p className="text-sm text-gray-500 mb-4">المادة: <span className="font-bold text-gray-800 dark:text-white">{material.name}</span></p>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block mb-1 text-sm font-medium">الكمية المضافة</label>
                        <input type="number" min="1" value={amount} onChange={(e) => setAmount(Number(e.target.value))} required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                    </div>
                    <div>
                        <label className="block mb-1 text-sm font-medium">السبب / المصدر</label>
                        <select value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600">
                            <option value="توريد جديد">توريد جديد</option>
                            <option value="مرتجع من مستلم">مرتجع من مستلم</option>
                            <option value="تصحيح مخزون">تصحيح مخزون (+)</option>
                            <option value="أخرى">أخرى</option>
                        </select>
                    </div>
                    <div>
                        <label className="block mb-1 text-sm font-medium">ملاحظات إضافية</label>
                        <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="مثلاً: اسم المستلم الذي أعاد المادة" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" rows={2} />
                    </div>
                    <div className="flex justify-end space-x-2 space-x-reverse pt-2">
                        <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                        <button type="submit" className="px-4 py-2 bg-emerald-500 text-white rounded">تأكيد الإضافة</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const MaterialModal: React.FC<{ material: Partial<Material> | null; onClose: () => void; onSave: (material: Omit<Material, 'id' | 'isNew'> | Material) => void; }> = ({ material, onClose, onSave }) => {
    const [formData, setFormData] = useState({
        name: material?.name || '',
        materialType: material?.materialType || '',
        category: material?.category || '',
        specifications: material?.specifications || '',
        supplier: material?.supplier || '',
        barcode: material?.barcode || '',
        unit: material?.unit || '',
        minStock: material?.minStock || 0,
        currentStock: material?.currentStock || 0,
    });

    const isEditing = !!material?.id;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: name === 'minStock' || name === 'currentStock' ? Number(value) : value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(isEditing ? { ...formData, id: material.id!, isNew: material.isNew! } : formData);
    };

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">{isEditing ? 'تعديل المادة' : 'إضافة مادة جديدة'}</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
                <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="اسم المادة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="materialType" value={formData.materialType} onChange={handleChange} placeholder="نوع المادة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="category" value={formData.category} onChange={handleChange} placeholder="الفئة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="supplier" value={formData.supplier} onChange={handleChange} placeholder="المورد" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="barcode" value={formData.barcode} onChange={handleChange} placeholder="الباركود" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <textarea name="specifications" value={formData.specifications} onChange={handleChange} placeholder="المواصفات" required rows={3} className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="unit" value={formData.unit} onChange={handleChange} placeholder="الوحدة (كرتونة، حبة)" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="number" name="minStock" value={formData.minStock} onChange={handleChange} placeholder="الحد الأدنى للمخزون" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="number" name="currentStock" value={formData.currentStock} onChange={handleChange} placeholder="الكمية الحالية" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <div className="flex justify-end space-x-2 space-x-reverse pt-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                    <button type="submit" className="px-4 py-2 bg-sky-500 text-white rounded">{isEditing ? 'حفظ التعديلات' : 'إضافة'}</button>
                </div>
            </form>
        </div>
      </div>
    );
};

const Materials: React.FC<MaterialsProps> = ({ materials, onDataChange, userRole, settings }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isStockInModalOpen, setIsStockInModalOpen] = useState(false);
  const [selectedMaterial, setSelectedMaterial] = useState<Material | null>(null);
  const [materialToDelete, setMaterialToDelete] = useState<Material | null>(null);

  const handleSave = (material: Omit<Material, 'id' | 'isNew'> | Material) => {
    if ('id' in material) { updateMaterial(material); } else { addMaterial(material); }
    onDataChange(); setIsModalOpen(false); setSelectedMaterial(null);
  };

  const handleStockIn = (amount: number, reason: string, note: string) => {
    if (!selectedMaterial) return;
    addTransaction({
        type: 'in',
        materialId: selectedMaterial.id,
        quantity: amount,
        recipient: reason, // In 'in' mode, recipient acts as source/reason
        notes: note,
    });
    onDataChange();
    setIsStockInModalOpen(false);
    setSelectedMaterial(null);
  };

  const handleDelete = (id: string) => { deleteMaterial(id); onDataChange(); setMaterialToDelete(null); };
  const handleAcknowledge = (id: string) => { acknowledgeNewMaterial(id); onDataChange(); };

  const handleExport = () => {
    const dataToExport = materials.map(m => ({ "اسم المادة": m.name, "نوع المادة": m.materialType, "الفئة": m.category, "المورد": m.supplier, "الباركود": m.barcode, "الوحدة": m.unit, "الكمية الحالية": m.currentStock, "الحد الأدنى": m.minStock, "المواصفات": m.specifications, }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "المواد");
    XLSX.writeFile(workbook, "materials_report.xlsx");
  };

  const handlePrint = () => {
    const reportTitle = `تقرير جرد المواد`;
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    printWindow.document.write(`
      <html><head><title>${reportTitle}</title><style>
            @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap');
            body { font-family: 'Cairo', sans-serif; direction: rtl; margin: 20px; }
            .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #ccc; padding-bottom: 10px; margin-bottom: 20px; }
            table { width: 100%; border-collapse: collapse; font-size: 0.9em; }
            th, td { border: 1px solid #ddd; padding: 8px; text-align: right; }
            th { background-color: #f2f2f2; }
          </style></head><body><div class="header">${settings?.companyLogo ? `<img src="${settings.companyLogo}" style="max-width:80px">` : ''}<div><h2>${settings?.companyName || ''}</h2><p>${settings?.companyAddress || ''}</p></div></div><h2 style="text-align:center">${reportTitle}</h2><table><thead><tr><th>اسم المادة</th><th>الباركود</th><th>الكمية الحالية</th><th>الحد الأدنى</th></tr></thead><tbody>${materials.map(m => `<tr><td>${m.name}</td><td>${m.barcode}</td><td>${m.currentStock} ${m.unit}</td><td>${m.minStock} ${m.unit}</td></tr>`).join('')}</tbody></table><script>setTimeout(() => { window.print(); window.close(); }, 500);</script></body></html>
    `);
    printWindow.document.close();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center flex-wrap gap-2">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">إدارة المواد</h1>
        {userRole === 'admin' && (
          <div className="flex items-center gap-2">
            <button onClick={handleExport} className="flex items-center px-4 py-2 bg-emerald-500 text-white rounded-lg shadow hover:bg-emerald-600"><Download className="ml-2" size={18} />تصدير XLSX</button>
            <button onClick={handlePrint} className="flex items-center px-4 py-2 bg-sky-500 text-white rounded-lg shadow hover:bg-sky-600"><Printer className="ml-2" size={18} />طباعة</button>
            <button onClick={() => { setSelectedMaterial(null); setIsModalOpen(true); }} className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700"><Plus className="ml-2" size={20} />إضافة مادة</button>
          </div>
        )}
      </div>

      <div className="bg-white dark:bg-gray-800 shadow-md rounded-lg overflow-x-auto">
        <table className="w-full text-sm text-right text-gray-500 dark:text-gray-400">
          <thead className="text-xs text-gray-700 uppercase bg-gray-50 dark:bg-gray-700 dark:text-gray-400">
            <tr>
              <th scope="col" className="px-6 py-3">اسم المادة</th>
              <th scope="col" className="px-6 py-3">الباركود</th>
              <th scope="col" className="px-6 py-3">الكمية الحالية</th>
              <th scope="col" className="px-6 py-3">الحد الأدنى</th>
              <th scope="col" className="px-6 py-3">المورد</th>
              {userRole === 'admin' && <th scope="col" className="px-6 py-3 text-center">إجراءات</th>}
            </tr>
          </thead>
          <tbody>
            {materials.map(material => (
              <tr key={material.id} className={`border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 ${material.isNew ? 'bg-red-50 dark:bg-red-900/10' : 'bg-white dark:bg-gray-800'}`}>
                <td className="px-6 py-4 font-medium text-gray-900 whitespace-nowrap dark:text-white">{material.name}</td>
                <td className="px-6 py-4 font-mono">{material.barcode}</td>
                <td className={`px-6 py-4 font-bold ${material.currentStock < material.minStock ? 'text-red-500' : 'text-emerald-500'}`}>
                    {material.currentStock} {material.unit}
                    {material.currentStock < material.minStock && <AlertTriangle className="inline-block mr-1 text-red-500" size={16}/>}
                </td>
                <td className="px-6 py-4">{material.minStock} {material.unit}</td>
                <td className="px-6 py-4">{material.supplier}</td>
                {userRole === 'admin' && (
                  <td className="px-6 py-4 flex items-center justify-center gap-3">
                    <button onClick={() => { setSelectedMaterial(material); setIsStockInModalOpen(true); }} className="text-emerald-500 hover:text-emerald-700 flex flex-col items-center" title="إضافة كمية / مرتجع">
                        <PlusCircle size={22}/>
                        <span className="text-[10px] mt-0.5">زيادة</span>
                    </button>
                    {material.isNew && (
                        <button onClick={() => handleAcknowledge(material.id)} className="text-sky-500 hover:text-sky-700" title="تأكيد الاستلام"><CheckCircle size={22}/></button>
                    )}
                    <button onClick={() => { setSelectedMaterial(material); setIsModalOpen(true); }} className="text-blue-500 hover:text-blue-700" title="تعديل"><Edit size={22}/></button>
                    <button onClick={() => setMaterialToDelete(material)} className="text-red-500 hover:text-red-700" title="حذف"><Trash2 size={22}/></button>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && <MaterialModal material={selectedMaterial} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
      {isStockInModalOpen && selectedMaterial && <StockInModal material={selectedMaterial} onClose={() => setIsStockInModalOpen(false)} onSave={handleStockIn} />}

      {materialToDelete && (
         <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-sm text-center">
                <h3 className="text-lg font-bold mb-4">تأكيد الحذف</h3>
                <p>هل أنت متأكد من حذف المادة "{materialToDelete.name}"؟</p>
                <div className="flex justify-center space-x-4 space-x-reverse mt-6">
                    <button onClick={() => setMaterialToDelete(null)} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                    <button onClick={() => handleDelete(materialToDelete.id)} className="px-4 py-2 bg-red-500 text-white rounded">حذف</button>
                </div>
            </div>
         </div>
      )}
    </div>
  );
};

export default Materials;

import React, { useState } from 'react';
import { Transaction, Material } from '@/types';
import { addTransaction } from '@/services/mockApi';
import { Plus, ArrowDownLeft, ArrowUpRight } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  materials: Material[];
  onDataChange: () => void;
  userRole: 'admin' | 'visitor';
}

const TransactionModal: React.FC<{ materials: Material[], onClose: () => void; onSave: (transaction: Omit<Transaction, 'id' | 'materialName' | 'date' | 'supplier' | 'category' | 'barcode' | 'unit' | 'materialType'>) => void; }> = ({ materials, onClose, onSave }) => {
    const [materialId, setMaterialId] = useState(materials[0]?.id || '');
    const [quantity, setQuantity] = useState(1);
    const [recipient, setRecipient] = useState('');
    const [notes, setNotes] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const selectedMaterial = materials.find(m => m.id === materialId);
        if (!selectedMaterial) { setError('الرجاء اختيار مادة.'); return; }
        if (quantity > selectedMaterial.currentStock) { setError('الكمية المسحوبة أكبر من المتاح.'); return; }
        onSave({ type: 'out', materialId, quantity, recipient, notes });
    };

    const selectedMaterial = materials.find(m => m.id === materialId);

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">إضافة حركة صرف (صادر)</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block mb-1 text-sm">المادة</label>
                    <select value={materialId} onChange={(e) => setMaterialId(e.target.value)} required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600">
                        {materials.map(m => <option key={m.id} value={m.id}>{m.name} (المتاح: {m.currentStock} {m.unit})</option>)}
                    </select>
                </div>
                <input type="number" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} placeholder="الكمية المسحوبة" min="1" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" value={recipient} onChange={(e) => setRecipient(e.target.value)} placeholder="اسم المستلم" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="ملاحظات" className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600"></textarea>
                {error && <p className="text-sm text-red-500">{error}</p>}
                <div className="flex justify-end space-x-2 space-x-reverse">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                    <button type="submit" className="px-4 py-2 bg-sky-500 text-white rounded">حفظ الحركة</button>
                </div>
            </form>
        </div>
      </div>
    );
};

const Transactions: React.FC<TransactionsProps> = ({ transactions, materials, onDataChange, userRole }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const sortedTransactions = [...transactions].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleSave = (transaction: any) => {
    addTransaction(transaction);
    onDataChange();
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">الحركات اليومية</h1>
        {userRole === 'admin' && (
            <button onClick={() => setIsModalOpen(true)} className="flex items-center px-4 py-2 bg-sky-500 text-white rounded-lg shadow hover:bg-sky-600 disabled:bg-sky-300" disabled={materials.length === 0}>
                <Plus className="ml-2" size={20} /> إضافة حركة صرف
            </button>
        )}
      </div>

      <div className="bg-white dark:bg-gray-800 shadow-md rounded-lg overflow-x-auto">
        <table className="w-full text-sm text-right text-gray-500 dark:text-gray-400">
          <thead className="text-xs text-gray-700 uppercase bg-gray-50 dark:bg-gray-700 dark:text-gray-400">
            <tr>
              <th scope="col" className="px-6 py-3">التاريخ</th>
              <th scope="col" className="px-6 py-3">نوع الحركة</th>
              <th scope="col" className="px-6 py-3">اسم المادة</th>
              <th scope="col" className="px-6 py-3">الكمية</th>
              <th scope="col" className="px-6 py-3">المستلم / السبب</th>
              <th scope="col" className="px-6 py-3">ملاحظات</th>
            </tr>
          </thead>
          <tbody>
            {sortedTransactions.map(transaction => (
              <tr key={transaction.id} className="bg-white border-b dark:bg-gray-800 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                <td className="px-6 py-4 text-xs">{new Date(transaction.date).toLocaleString('ar-EG')}</td>
                <td className="px-6 py-4">
                    {transaction.type === 'in' ? (
                        <span className="flex items-center text-emerald-600 dark:text-emerald-400 font-bold">
                            <ArrowUpRight size={16} className="ml-1"/> وارد / مرتجع
                        </span>
                    ) : (
                        <span className="flex items-center text-gray-600 dark:text-gray-400">
                            <ArrowDownLeft size={16} className="ml-1"/> صادر / صرف
                        </span>
                    )}
                </td>
                <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{transaction.materialName}</td>
                <td className={`px-6 py-4 font-bold ${transaction.type === 'in' ? 'text-emerald-500' : ''}`}>
                    {transaction.type === 'in' ? '+' : '-'}{transaction.quantity} {transaction.unit}
                </td>
                <td className="px-6 py-4">{transaction.recipient}</td>
                <td className="px-6 py-4 text-xs">{transaction.notes}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && <TransactionModal materials={materials.filter(m => m.currentStock > 0)} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
    </div>
  );
};

export default Transactions;

import React, { useState } from 'react';
import { Material, SettingsData, Transaction } from '@/types';
import { addMaterial, updateMaterial, deleteMaterial, acknowledgeNewMaterial, addTransaction } from '@/services/mockApi';
import { Plus, Edit, Trash2, AlertTriangle, Printer, Download, CheckCircle, PlusCircle, RotateCcw } from 'lucide-react';
import * as XLSX from 'xlsx';

interface MaterialsProps {
  materials: Material[];
  onDataChange: () => void;
  userRole: 'admin' | 'visitor';
  settings: SettingsData | null;
}

// Modal for Adding/Returning Stock (Incremental)
const StockInModal: React.FC<{ 
    material: Material; 
    actionType: 'supply' | 'return';
    onClose: () => void; 
    onSave: (amount: number, reason: string, note: string) => void; 
}> = ({ material, actionType, onClose, onSave }) => {
    const [amount, setAmount] = useState(1);
    const [reason, setReason] = useState(actionType === 'supply' ? 'توريد جديد' : 'مرتجع من مستلم');
    const [note, setNote] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(amount, reason, note);
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md">
                <div className="flex items-center gap-2 mb-2">
                    {actionType === 'supply' ? <PlusCircle className="text-emerald-500" /> : <RotateCcw className="text-amber-500" />}
                    <h2 className="text-xl font-bold">{actionType === 'supply' ? 'توريد كمية جديدة' : 'إرجاع مادة للمستودع'}</h2>
                </div>
                <p className="text-sm text-gray-500 mb-4">المادة: <span className="font-bold text-gray-800 dark:text-white">{material.name}</span></p>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block mb-1 text-sm font-medium">الكمية</label>
                        <input type="number" min="1" value={amount} onChange={(e) => setAmount(Number(e.target.value))} required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                    </div>
                    <div>
                        <label className="block mb-1 text-sm font-medium">السبب / المصدر</label>
                        <select value={reason} onChange={(e) => setReason(e.target.value)} className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600">
                            {actionType === 'supply' ? (
                                <>
                                    <option value="توريد جديد">توريد جديد</option>
                                    <option value="تصحيح مخزون">تصحيح مخزون (+)</option>
                                </>
                            ) : (
                                <>
                                    <option value="مرتجع من مستلم">مرتجع من مستلم</option>
                                    <option value="مرتجع تالف">مرتجع تالف</option>
                                    <option value="إلغاء عملية صرف">إلغاء عملية صرف</option>
                                </>
                            )}
                            <option value="أخرى">أخرى</option>
                        </select>
                    </div>
                    <div>
                        <label className="block mb-1 text-sm font-medium">ملاحظات إضافية</label>
                        <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder={actionType === 'return' ? "مثلاً: اسم الشخص الذي أعاد المادة" : "ملاحظات حول المورد أو الفاتورة"} className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" rows={2} />
                    </div>
                    <div className="flex justify-end space-x-2 space-x-reverse pt-2">
                        <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                        <button type="submit" className={`px-4 py-2 text-white rounded ${actionType === 'supply' ? 'bg-emerald-500' : 'bg-amber-500'}`}>
                            تأكيد {actionType === 'supply' ? 'التوريد' : 'المرتجع'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const MaterialModal: React.FC<{ material: Partial<Material> | null; onClose: () => void; onSave: (material: Omit<Material, 'id' | 'isNew'> | Material) => void; }> = ({ material, onClose, onSave }) => {
    const [formData, setFormData] = useState({
        name: material?.name || '',
        materialType: material?.materialType || '',
        category: material?.category || '',
        specifications: material?.specifications || '',
        supplier: material?.supplier || '',
        barcode: material?.barcode || '',
        unit: material?.unit || '',
        minStock: material?.minStock || 0,
        currentStock: material?.currentStock || 0,
    });

    const isEditing = !!material?.id;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: name === 'minStock' || name === 'currentStock' ? Number(value) : value }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(isEditing ? { ...formData, id: material.id!, isNew: material.isNew! } : formData);
    };

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-4">{isEditing ? 'تعديل المادة' : 'إضافة مادة جديدة'}</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
                <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="اسم المادة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="materialType" value={formData.materialType} onChange={handleChange} placeholder="نوع المادة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="category" value={formData.category} onChange={handleChange} placeholder="الفئة" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="supplier" value={formData.supplier} onChange={handleChange} placeholder="المورد" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="barcode" value={formData.barcode} onChange={handleChange} placeholder="الباركود" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <textarea name="specifications" value={formData.specifications} onChange={handleChange} placeholder="المواصفات" required rows={3} className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="text" name="unit" value={formData.unit} onChange={handleChange} placeholder="الوحدة (كرتونة، حبة)" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="number" name="minStock" value={formData.minStock} onChange={handleChange} placeholder="الحد الأدنى للمخزون" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <input type="number" name="currentStock" value={formData.currentStock} onChange={handleChange} placeholder="الكمية الحالية" required className="w-full p-2 border rounded dark:bg-gray-700 dark:border-gray-600" />
                <div className="flex justify-end space-x-2 space-x-reverse pt-2">
                    <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-300 dark:bg-gray-600 rounded">إلغاء</button>
                    <button type="submit" className="px-4 py-2 bg-sky-500 text-white rounded">{isEditing ? 'حفظ التعديلات' : 'إضافة'}</button>
                </div>
            </form>
        </div>
      </div>
    );
};

const Materials: React.FC<MaterialsProps> = ({ materials, onDataChange, userRole, settings }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isStockInModalOpen, setIsStockInModalOpen] = useState(false);
  const [stockActionType, setStockActionType] = useState<'supply' | 'return'>('supply');
  const [selectedMaterial, setSelectedMaterial] = useState<Material | null>(null);
  const [materialToDelete, setMaterialToDelete] = useState<Material | null>(null);

  const handleSave = (material: Omit<Material, 'id' | 'isNew'> | Material) => {
    if ('id' in material) { updateMaterial(material); } else { addMaterial(material); }
    onDataChange(); setIsModalOpen(false); setSelectedMaterial(null);
  };

  const handleStockIn = (amount: number, reason: string, note: string) => {
    if (!selectedMaterial) return;
    addTransaction({
        type: 'in',
        materialId: selectedMaterial.id,
        quantity: amount,
        recipient: reason,
        notes: note,
    });
    onDataChange();
    setIsStockInModalOpen(false);
    setSelectedMaterial(null);
  };

  const openStockModal = (material: Material, type: 'supply' | 'return') => {
      setSelectedMaterial(material);
      setStockActionType(type);
      setIsStockInModalOpen(true);
  };

  const handleDelete = (id: string) => { deleteMaterial(id); onDataChange(); setMaterialToDelete(null); };
  const handleAcknowledge = (id: string) => { acknowledgeNewMaterial(id); onDataChange(); };

  const handleExport = () => {
    const dataToExport = materials.map(m => ({ "اسم المادة": m.name, "نوع المادة": m.materialType, "الفئة": m.category, "المورد": m.supplier, "الباركود": m.barcode, "الوحدة": m.unit, "الكمية الحالية": m.currentStock, "الحد الأدنى": m.minStock, "المواصفات": m.specifications, }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "المواد");
    XLSX.writeFile(workbook, "materials_report.xlsx");
  };

  const handlePrint = () => {
    const reportTitle = `تقرير جرد المواد`;
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;
    printWindow.document.write(`
      <html><head><title>${reportTitle}</title><style>
            @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap');
            body { font-family: 'Cairo', sans-serif; direction: rtl; margin: 20px; }
            .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #ccc; padding-bottom: 10px; margin-bottom: 20px; }
            table { width: 100%; border-collapse: collapse; font-size: 0.9em; }
            th, td { border: 1px solid #ddd; padding: 8px; text-align: right; }
            th { background-color: #f2f2f2; }
          </style></head><body><div class="header">${settings?.companyLogo ? `<img src="${settings.companyLogo}" style="max-width:80px">` : ''}<div><h2>${settings?.companyName || ''}</h2><p>${settings?.companyAddress || ''}</p></div></div><h2 style="text-align:center">${reportTitle}</h2><table><thead><tr><th>اسم المادة</th><th>الباركود</th><th>الكمية الحالية</th><th>الحد الأدنى</th></tr></thead><tbody>${materials.map(m => `<tr><td>${m.name}</td><td>${m.barcode}</td><td>${m.currentStock} ${m.unit}</td><td>${m.minStock} ${m.unit}</td></tr>`).join('')}</tbody></table><script>setTimeout(() => { window.print(); window.close(); }, 500);</script></body></html>
    `);
    printWindow.document.close();
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center flex-wrap gap-2">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">إدارة المواد</h1>
        {userRole === 'admin' && (
          <div className="flex items-center gap-2">
            <button onClick={handleExport} className="flex items-center px-4 py-2 bg-emerald-500 text-white rounded-lg shadow hover:bg-emerald-600"><Download className="ml-2" size={18} />تصدير XLSX</button>
            <button onClick={handlePrint} className="flex items-center px-4 py-2 bg-sky-500 text-white rounded-lg shadow hover:bg-sky-600"><Printer className="ml-2" size={18} />طباعة</button>
            <button onClick={() => { setSelectedMaterial(null); setIsModalOpen(true); }} className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg shadow hover:bg-blue-700"><Plus className="ml-2" size={20} />إضافة مادة</button>
          </div>
        )}
      </div>

      <div className="bg-white dark:bg-gray-800 shadow-md rounded-lg overflow-x-auto">
        <table className="w-full text-sm text-right text-gray-500 dark:text-gray-400">
          <thead className="text-xs text-gray-700 uppercase bg-gray-50 dark:bg-gray-700 dark:text-gray-400">
            <tr>
              <th scope="col" className="px-6 py-3">اسم المادة</th>
              <th scope="col" className="px-6 py-3">الباركود</th>
              <th scope="col" className="px-6 py-3">الكمية الحالية</th>
              <th scope="col" className="px-6 py-3">الحد الأدنى</th>
              <th scope="col" className="px-6 py-3">المورد</th>
              {userRole === 'admin' && <th scope="col" className="px-6 py-3 text-center">إجراءات سريعة</th>}
              {userRole === 'admin' && <th scope="col" className="px-6 py-3 text-center">إدارة</th>}
            </tr>
          </thead>
          <tbody>
            {materials.map(material => (
              <tr key={material.id} className={`border-b dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600 ${material.isNew ? 'bg-red-50 dark:bg-red-900/10' : 'bg-white dark:bg-gray-800'}`}>
                <td className="px-6 py-4 font-medium text-gray-900 whitespace-nowrap dark:text-white">{material.name}</td>
                <td className="px-6 py-4 font-mono">{material.barcode}</td>
                <td className={`px-6 py-4 font-bold ${material.currentStock < material.minStock ? 'text-red-500' : 'text-emerald-500'}`}>
                    {material.currentStock} {material.unit}
                    {material.currentStock < material.minStock && <AlertTriangle className="inline-block mr-1 text-red-500" size={16}/>}
                </td>
                <td className="px-6 py-4">{material.minStock} {material.unit}</td>
                <td className="px-6 py-4">{material.supplier}</td>
                {userRole === 'admin' && (
                  <td className="px-6 py-4 flex items-center justify-center gap-4">
                    <button onClick={() => openStockModal(material, 'supply')} className="text-emerald-500 hover:text-emerald-700 flex flex-col items-center" title="توريد جديد">
                        <PlusCircle size={22}/>
                        <span className="text-[10px] mt-0.5">توريد</span>
                    </button>
                    <button onClick={() => openStockModal(material, 'return')} className="text-amber-500 hover:text-amber-700 flex flex-col items-center" title="مرتجع من مستلم">
                        <RotateCcw size={22}/>
                        <span className="text-[10px] mt-0.5">مرتجع</span>
                    </button>
                  </td>
                )}
                {userRole === 'admin' && (
                  <td className="px-6 py-4 flex items-center justify-center gap-3 border-r dark:border-gray-700">
                    {material.isNew && (
                        <button onClick={() => handleAcknowledge(material.id)} className="text-sky-500 hover:text-sky-700" title="تأكيد الاستلام"><CheckCircle size={22}/></button>
                    )}
                    <button onClick={() => { setSelectedMaterial(material); setIsModalOpen(true); }} className="text-blue-500 hover:text-blue-700" title="تعديل"><Edit size={22}/></button>
                    <button onClick={() => setMaterialToDelete(material)} className="text-red-500 hover:text-red-700" title="حذف"><Trash2 size={22}/></button>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isModalOpen && <MaterialModal material={selectedMaterial} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
      {isStockInModalOpen && selectedMaterial && (
          <StockInModal 
            material={selectedMaterial} 
            actionType={stockActionType}
            onClose={() => setIsStockInModalOpen(false)} 
            onSave={handleStockIn} 
          />
      )}

      {materialToDelete && (
         <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center">
